abstract class Shape {
  kind: string;
  constructor() {
    if (new.target === Shape) throw new TypeError("abstract");
    this.kind = new.target.name;
  }
}
class Sq extends Shape {}
class Big extends Sq { constructor() { super(); console.log("big", new.target === Big, new.target === Sq, new.target !== Sq, new.target.name); } }
class MyErr extends Error {
  constructor(m: string) {
    super(m);
    Object.setPrototypeOf(this, new.target.prototype);
    this.name = new.target.name;
  }
}
class SubErr extends MyErr {}
function plain() { return new.target === undefined; }
function main(): void {
  console.log(new Sq() instanceof Shape, new Sq().kind, new Big().kind);
  try { throw new MyErr("a"); } catch (e: any) { console.log(e instanceof MyErr, e instanceof Error, e.name, e.message); }
  try { throw new SubErr("b"); } catch (e: any) { console.log(e instanceof SubErr, e instanceof MyErr, e.name, e.message); }
  console.log(plain());
  const f = () => 1;
  console.log(f());
}
